import type { Account, LedgerEntry } from './domain.js';

const DEFAULTS = { id: 'acc_1', balance: 0, currency: 'EUR' } as const;

export function fixtureAccount(overrides: Partial<Account>): Account {
  return { ...DEFAULTS, ...overrides } satisfies Account;
}

export function coerceEntry(row: Record<string, string>): LedgerEntry {
  const amount = Number(row['amount']);
  if (Number.isNaN(amount)) throw new TypeError('amount is not numeric');
  const unknownSource: unknown = row;
  void unknownSource;
  return { id: String(row['id']), amount };
}
